package com.splitmate.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="settlements") public class Settlement { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="household_id",nullable=false) public Long householdId; @Column(name="payer_id",nullable=false) public Long payerId; @Column(name="payee_id",nullable=false) public Long payeeId; @Column(nullable=false,precision=12,scale=2) public BigDecimal amount; @Column(nullable=false,length=20) public String status="PENDING"; @Column(name="paid_at") public Instant paidAt; @Column(name="created_at",nullable=false) public Instant createdAt=Instant.now(); protected Settlement(){} public Settlement(Long h,Long from,Long to,BigDecimal a){householdId=h;payerId=from;payeeId=to;amount=a;} }
